1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Base premiums per item type ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const scenario = {
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    };
11	
12	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("single sword → base premium 100 G");
15	  it.todo("single amulet → base premium 60 G");
16	  it.todo("single staff → base premium 80 G");
17	  it.todo("single potion → base premium 40 G");
18	  it.todo("single rune → base premium 25 G");
19	  it.todo("single moonstone → base premium 25 G");
20	
21	  // --- Building block of 3 alike components ---
22	  it.todo("2 runes → 50 G base premium");
23	  it.todo("3 runes → 60 G base premium (block applies)");
24	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
25	  it.todo("7 runes → 175 G base premium");
26	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
27	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
28	
29	  // --- Item-specific modifiers ---
30	  it.todo("cursed sword adds a 50 % surcharge on that item's base premium");
31	  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge");
32	  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
33	  it.todo("cursed sword with enchantment 5 gets both surcharges");
34	
35	  // --- Modifier scope on multi-item policies ---
36	  it.todo(
37	    "cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only the cursed item's base) → 210 G before further modifiers and fee",
38	  );
39	
40	  // --- Policy-wide modifiers ---
41	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
42	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
43	  it.todo("each item in a quote carries a 10 % first insurance surcharge");
44	  it.todo("the second quote of a customer receives a 15 % follow-up contract discount");
45	  it.todo("a 5 G processing fee is added to every premium");
46	
47	  // --- Rounding ---
48	  it.todo("premium of 197.5 G is rounded up to 198 G (MHPCO's favour)");
49	  it.todo("payout of 350.5 G is rounded down to 350 G (MHPCO's favour)");
50	
51	  // --- Integration examples ---
52	  it.todo("newcomer (0 years) with a cursed steel sword, enchantment 3 → premium 165 G");
53	  it.todo(
54	    "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
55	  );
56	
57	  // --- Claim: standard reimbursement ---
58	  it.todo("steel sword, enchantment 3, damage 500 G → payout 400 G (damage minus deductible)");
59	  it.todo("rune (no enchantment, no material), damage 200 G → payout 100 G");
60	
61	  // --- Claim: special clauses ---
62	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
63	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
64	  it.todo("dragon-material sword, enchantment 8, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
65	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");
66	
67	  // --- Claim: deductible per damage event ---
68	  it.todo(
69	    "dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)",
70	  );
71	
72	  // --- Claim: cap ---
73	  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
74	  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G (block affects premium only)");
75	  it.todo("cursed sword → cap 2000 G based on the unmodified insurance value");
76	  it.todo("sword policy, first claim of 1500 G → payout 1400 G, remaining cap 600 G");
77	  it.todo("sword policy, second claim of 1500 G → payout 600 G, remaining cap 0 G");
78	
79	  // --- Multiple items of the same type ---
80	  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
81	  it.todo("two sword damage entries → each treated as a separate damage with its own deductible");
82	  it.todo("more damage entries of a type than insured → the claim is rejected with an error");
83	
84	  // --- Errors ---
85	  it.todo("quote with an unknown item type (broomstick) → error");
86	  it.todo("claim for an item not part of the policy → error");
87	  it.todo("claim with a damage entry of unknown item type → error");
88	  it.todo("claim with a negative damage amount (-200) → error");
89	
90	  // --- CLI ---
91	  it.todo("CLI reads a scenario from stdin and writes {results:[...]} to stdout");
92	  it.todo("CLI exits with a non-zero status and writes to stderr on an unknown item type, with no results on stdout");
93	});
